#!/usr/bin/env python3
"""Generate BisQue runtime config from the public BISQUE_* environment."""

from __future__ import annotations

import argparse
import os
import re
import shutil
import sys
import uuid
from pathlib import Path
from urllib.parse import urlparse

GENERATED = (
    "# Generated by scripts/generate-config.py. Do not edit by hand.\n"
    "# Edit .env or exported BISQUE_* variables, then run just setup."
)


def env(name: str, default: str) -> str:
    value = os.environ.get(name)
    return value if value not in (None, "") else default


def as_bool(value: str, default: bool = False) -> bool:
    if value == "":
        return default
    normalized = value.strip().lower()
    if normalized in {"1", "true", "yes", "on", "y"}:
        return True
    if normalized in {"0", "false", "no", "off", "n"}:
        return False
    raise SystemExit(f"Expected boolean value, got {value!r}")


def validate_dburl(dburl: str) -> str:
    parsed = urlparse(dburl)
    if not parsed.scheme:
        raise SystemExit(f"BISQUE_DBURL must include a scheme: {dburl!r}")
    if parsed.scheme == "sqlite" and not dburl.startswith("sqlite:///"):
        raise SystemExit("sqlite BISQUE_DBURL must use sqlite:///path/to/db")
    return dburl


def resolve_path_list(value: str, base: Path) -> str:
    paths = []
    for item in value.split(","):
        item = item.strip()
        if not item:
            continue
        path = Path(item).expanduser()
        if not path.is_absolute():
            path = base / path
        paths.append(path.resolve().as_posix())
    return ",".join(paths)


def read_existing_value(path: Path, key: str) -> str | None:
    if not path.exists():
        return None
    pattern = re.compile(rf"^\s*{re.escape(key)}\s*=\s*(.*)\s*$")
    for line in path.read_text(errors="ignore").splitlines():
        match = pattern.match(line)
        if match:
            return match.group(1).strip()
    return None


def backup_if_changed(path: Path, content: str) -> None:
    if not path.exists():
        return
    old = path.read_text(errors="ignore")
    if old == content:
        return
    backup = path.with_suffix(path.suffix + ".bak")
    counter = 1
    while backup.exists():
        backup = path.with_suffix(path.suffix + f".bak{counter}")
        counter += 1
    shutil.copy2(path, backup)


def write_generated(path: Path, content: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    backup_if_changed(path, content)
    path.write_text(content)


def copy_default(defaults_dir: Path, name: str, target: Path) -> None:
    source = defaults_dir / f"{name}.default"
    if not source.exists():
        return
    if target.exists():
        return
    target.parent.mkdir(parents=True, exist_ok=True)
    shutil.copyfile(source, target)


def set_section_value(path: Path, section: str, key: str, value: str) -> None:
    lines = path.read_text(errors="ignore").splitlines()
    in_section = False
    section_seen = False
    updated = False
    output: list[str] = []

    for line in lines:
        stripped = line.strip()
        if stripped.startswith("[") and stripped.endswith("]"):
            if in_section and not updated:
                output.append(f"{key} = {value}")
                updated = True
            in_section = stripped == f"[{section}]"
            section_seen = section_seen or in_section
        if in_section and stripped.startswith(f"{key}"):
            output.append(f"{key} = {value}")
            updated = True
            continue
        output.append(line)

    if section_seen and in_section and not updated:
        output.append(f"{key} = {value}")
    elif not section_seen:
        output.extend(["", f"[{section}]", f"{key} = {value}"])

    path.write_text("\n".join(output) + "\n")


