def make_alembic_cfg(defaults_dir: Path, values: dict[str, str]) -> str:
    source = defaults_dir / "alembic.ini.default"
    if source.exists():
        text = source.read_text()
        text = re.sub(
            r"^sqlalchemy\.url\s*=.*$",
            f"sqlalchemy.url = {values['dburl']}",
            text,
            flags=re.MULTILINE,
        )
        return f"{GENERATED}\n" + text
    return f"{GENERATED}\n[alembic]\nscript_location = migrations\nsqlalchemy.url = {values['dburl']}\n"


def build_values(root: Path, args: argparse.Namespace) -> dict[str, str]:
    runtime_dir = Path(env("BISQUE_RUNTIME_DIR", str(root / ".bisque"))).expanduser().resolve()
    config_dir = Path(env("BISQUE_CONFIG_DIR", str(runtime_dir / "config"))).expanduser().resolve()
    data_dir = Path(env("BISQUE_DATA_DIR", str(runtime_dir / "data"))).expanduser().resolve()
    external_dir = (
        Path(env("BISQUE_EXTERNAL_DIR", str(runtime_dir / "external"))).expanduser().resolve()
    )
    public_dir = Path(env("BISQUE_PUBLIC_DIR", str(runtime_dir / "public"))).expanduser().resolve()
    reports_dir = (
        Path(env("BISQUE_REPORTS_DIR", str(runtime_dir / "reports"))).expanduser().resolve()
    )
    staging_dir = (
        Path(env("BISQUE_STAGING_DIR", str(runtime_dir / "staging"))).expanduser().resolve()
    )
    log_dir = Path(env("BISQUE_LOG_DIR", str(runtime_dir / "logs"))).expanduser().resolve()
    run_dir = Path(env("BISQUE_RUN_DIR", str(runtime_dir / "run"))).expanduser().resolve()
    upload_tmp = os.environ.get("BISQUE_UPLOAD_TMP_DIR", "")
    upload_dir = Path(upload_tmp).expanduser().resolve() if upload_tmp else data_dir / "uploads"

    http_host = env("BISQUE_HTTP_HOST", "0.0.0.0")
    http_port = env("BISQUE_HTTP_PORT", "8080")
    public_url = env("BISQUE_PUBLIC_URL", f"http://localhost:{http_port}")
    dburl = validate_dburl(env("BISQUE_DBURL", f"sqlite:///{data_dir / 'bisque.db'}"))
    site_cfg = config_dir / "site.cfg"
    existing_secret = read_existing_value(site_cfg, "beaker.session.secret")
    secret = env("BISQUE_SECRET", existing_secret or uuid.uuid4().hex)
    venv = Path(env("VENV", str(root / ".venv"))).expanduser().resolve()
    python_version = env("PYTHON_VERSION", f"{sys.version_info.major}.{sys.version_info.minor}")
    enable_engine_service = as_bool(env("BISQUE_ENABLE_ENGINE_SERVICE", "true"), True)
    services_enabled = env("BISQUE_SERVICES_ENABLED", "")
    services_disabled = os.environ.get("BISQUE_SERVICES_DISABLED")
    if services_disabled is None:
        services_disabled = "" if enable_engine_service else "engine_service"

    return {
        "root": root.as_posix(),
        "source_dir": (root / "source").resolve().as_posix(),
        "runtime_dir": runtime_dir.as_posix(),
        "config_dir": config_dir.as_posix(),
        "data_dir": data_dir.as_posix(),
        "external_dir": external_dir.as_posix(),
        "public_dir": public_dir.as_posix(),
        "reports_dir": reports_dir.as_posix(),
        "staging_dir": staging_dir.as_posix(),
        "log_dir": log_dir.as_posix(),
        "run_dir": run_dir.as_posix(),
        "upload_dir": upload_dir.as_posix(),
        "http_host": http_host,
        "http_port": http_port,
        "public_url": public_url,
        "services_enabled": services_enabled,
        "services_disabled": services_disabled,
        "dburl": dburl,
        "secret": secret,
        "venv": venv.as_posix(),
        "packages_dir": (venv / "lib" / f"python{python_version}" / "site-packages").as_posix(),
        "defaults_dir": (root / "source" / "config-defaults").resolve().as_posix(),
        "module_dirs": resolve_path_list(
            env("BISQUE_MODULE_DIRS", (root / "source" / "modules").resolve().as_posix()),
            root,
        ),
        "fixture_dir": env(
            "BISQUE_TEST_INPUT_DIR",
            (root / "source" / "bqapi" / "bqapi" / "tests" / "fixtures").resolve().as_posix(),
        ),
        "docker_hub": os.environ.get("BISQUE_DOCKER_HUB", "nail04.ece.ucsb.edu:5000"),
        "docker_backend": env("BISQUE_DOCKER_BACKEND", "docker"),
        "docker_callback_url": env("BISQUE_DOCKER_CALLBACK_URL", ""),
        "docker_argo_workflow_template": env(
            "BISQUE_ARGO_WORKFLOW_TEMPLATE", "bqflow-module-template"
        ),
        "docker_argo_gpu_workflow_template": env(
            "BISQUE_ARGO_GPU_WORKFLOW_TEMPLATE", "bqflow-module-gpu-template"
        ),
        "organization": env("BISQUE_ORGANIZATION", "Your Organization"),
        "title": env("BISQUE_TITLE", "Image Repository"),
        "admin_email": env("BISQUE_ADMIN_EMAIL", "YourEmail@YourOrganization"),
        "js_environment": env("BISQUE_JS_ENVIRONMENT", "development"),
        "debug": "true" if as_bool(env("BISQUE_DEBUG", "true"), True) else "false",
        "smtp_host": env("BISQUE_SMTP_HOST", "localhost"),
        "smtp_port": env("BISQUE_SMTP_PORT", "587"),
        "smtp_user": env("BISQUE_SMTP_USER", ""),
        "smtp_password": env("BISQUE_SMTP_PASSWORD", ""),
        "smtp_tls": env("BISQUE_SMTP_TLS", "true").lower(),
        "smtp_ssl": env("BISQUE_SMTP_SSL", "false").lower(),
        "smtp_timeout": env("BISQUE_SMTP_TIMEOUT", "30"),
        "mail_from": env("BISQUE_MAIL_FROM", "noreply@localhost"),
        "mail_from_name": env("BISQUE_MAIL_FROM_NAME", "Bisque System"),
        "email_verification": env("BISQUE_EMAIL_VERIFICATION_ENABLED", "false").lower(),
    }


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--root", default=Path(__file__).resolve().parents[1])
    args = parser.parse_args()

    root = Path(args.root).expanduser().resolve()
    values = build_values(root, args)
    config_dir = Path(values["config_dir"])
    defaults_dir = Path(values["defaults_dir"])

    for key in (
        "data_dir",
        "external_dir",
        "public_dir",
        "reports_dir",
        "staging_dir",
        "log_dir",
        "run_dir",
        "upload_dir",
    ):
        Path(values[key]).mkdir(parents=True, exist_ok=True)
    config_dir.mkdir(parents=True, exist_ok=True)

    write_generated(config_dir / "site.cfg", make_site_cfg(values))
    write_generated(config_dir / "runtime-bisque.cfg", make_runtime_cfg(values))
    write_generated(config_dir / "h1_paster.cfg", make_paster_cfg(values))
    write_generated(config_dir / "test.ini", make_test_cfg(values))
    write_generated(config_dir / "alembic.ini", make_alembic_cfg(defaults_dir, values))

    copy_default(defaults_dir, "who.ini", config_dir / "who.ini")
    copy_default(defaults_dir, "registration.cfg", config_dir / "registration.cfg")
    copy_default(defaults_dir, "server.ini", config_dir / "server.ini")
    copy_default(defaults_dir, "shell.ini", config_dir / "shell.ini")
    set_section_value(config_dir / "who.ini", "plugin:auth_tkt", "secret", values["secret"])

    print(f"Generated BisQue config under {config_dir}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
